import { BrowserRouter, Navigate, Route, Routes } from "react-router-dom";

function App() {
    return (
        <BrowserRouter>
        <Routes>
            <Route path="/" element={<Navigate to ="/login"/>}/>
            <Route path="/login" element to ={<Login/>}/>
        </Routes>
        </BrowserRouter>
    )
}

export default App;
